import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

masked_cumsum_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <stdio.h>

// Naive masked inclusive cumsum along dim=1 for 2D tensors: [batch_size, length]
__global__ void masked_cumsum_kernel(
    const float* x,
    const bool* mask,
    float* out,
    int batch_size,
    int length
) {
    int row = blockIdx.x;
    if (row >= batch_size) return;

    int start_idx = row * length;
    float cumsum = 0.0f;
    for(int i = 0; i < length; i++) {
        int idx = start_idx + i;
        cumsum += mask[idx] ? x[idx] : 0.0f;
        out[idx] = cumsum;
    }
}

torch::Tensor masked_cumsum_cuda(
    torch::Tensor x,
    torch::Tensor mask,
    int dim
) {
    // For simplicity, assume x is 2D, dim=1
    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    TORCH_CHECK(mask.dim() == 2, "mask must be 2D");
    TORCH_CHECK(x.size(0) == mask.size(0) && x.size(1) == mask.size(1),
                "x and mask must have the same shape");
    TORCH_CHECK(dim == 1, "This custom kernel only supports dim=1");

    auto out = torch::zeros_like(x);
    int batch_size = x.size(0);
    int length = x.size(1);

    // Launch one block per row, single thread per block (naive approach)
    dim3 grid(batch_size);
    dim3 block(1);

    masked_cumsum_kernel<<<grid, block>>>(
        x.data_ptr<float>(),
        mask.data_ptr<bool>(),
        out.data_ptr<float>(),
        batch_size,
        length
    );

    return out;
}
""";

masked_cumsum_cpp_source = r"""
torch::Tensor masked_cumsum_cuda(torch::Tensor x, torch::Tensor mask, int dim);
""";

masked_cumsum = load_inline(
    name="masked_cumsum",
    cpp_sources=masked_cumsum_cpp_source,
    cuda_sources=masked_cumsum_source,
    functions=["masked_cumsum_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    A model that performs a masked cumulative sum, only summing elements that satisfy a condition,
    using a custom CUDA kernel.
    """

    def __init__(self, dim):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.masked_cumsum = masked_cumsum

    def forward(self, x, mask):
        return self.masked_cumsum.masked_cumsum_cuda(x, mask, self.dim)
